def digest(data):
    return hashlib.sha256(data).hexdigest()


def install(root, check=False):
    root = root.expanduser().resolve(strict=True)
    inventory = root / "ontology_inventory.txt"
    if inventory.is_symlink() or not inventory.is_file():
        raise RuntimeError("ontology_inventory.txt required; no files changed")
    if "reservation_recovery_manager" not in inventory.read_text(encoding="utf-8"):
        raise RuntimeError("existing module absent from inventory; no files changed")
    target = root / "ontology/reservation_recovery_manager.py"
    if target.is_symlink() or not target.is_file():
        raise RuntimeError("existing adapter required; no files changed")
    current = digest(target.read_bytes())
    expected = digest(OUTPUTS["ontology/reservation_recovery_manager.py"].encode("utf-8"))
    if current not in (BASE_SHA256, expected):
        raise RuntimeError("adapter source has changed; no files changed; SHA256=" + current)
    changes = []
    for relative, text in OUTPUTS.items():
        path = root / relative
        if path.is_symlink() or not path.resolve().is_relative_to(root):
            raise RuntimeError("unsafe target: " + relative)
        if path.exists() and not path.is_file():
            raise RuntimeError("non-file target: " + relative)
        data = text.encode("utf-8")
        compile(text, relative, "exec")
        old = path.read_bytes() if path.exists() else None
        if old == data:
            continue
        # Test/lock drift is also guarded; never overwrite unrelated local work.
        if relative != "ontology/reservation_recovery_manager.py" and old is not None:
            raise RuntimeError("different existing test/lock: " + relative)
        changes.append((path, old, data))
    print("SOURCE_PRECONDITION_PASS; files_to_change=" + str(len(changes)))
    if check:
        return
    # Prepare and verify every backup before the first replacement.
    for path, old, data in changes:
        if old is None:
            continue
        backup = path.with_name(path.name + "." + digest(old)[:16] + ".py.bak")
        if backup.is_symlink():
            raise RuntimeError("unsafe backup: " + str(backup))
        try:
            with backup.open("xb") as stream:
                stream.write(old)
                stream.flush()
                os.fsync(stream.fileno())
        except FileExistsError:
            if backup.read_bytes() != old:
                raise RuntimeError("backup mismatch: " + str(backup))
        print("BACKUP " + str(backup))
    completed = []
    try:
        for path, old, data in changes:
            # Recheck immediately before replacement to detect intervening edits.
            if path.is_symlink() or (path.read_bytes() if path.exists() else None) != old:
                raise RuntimeError("target changed during installation: " + str(path))
            path.parent.mkdir(parents=True, exist_ok=True)
            atomic_write(path, data)
            completed.append((path, old, data))
        print("P162_PC4_RECOVERY_REFINEMENT_INSTALLED")
        print("Run: python3 final_lock.py p162_pc4_recovery")
        print("P162_GLOBAL_FINAL_LOCK_NOT_EXECUTED")
    except BaseException:
        for path, old, data in reversed(completed):
            # Do not erase an intervening edit during rollback.
            if path.is_symlink() or not path.is_file() or path.read_bytes() != data:
                print("ROLLBACK_REQUIRES_REVIEW " + str(path))
                continue
            if old is None:
                path.unlink()
            else:
                atomic_write(path, old)
        raise


def atomic_write(path, data):
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    fd, temp = tempfile.mkstemp(prefix=".p162-pc4-", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temp, mode)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    try:
        install(args.root, check=args.check)
    except (OSError, RuntimeError, ValueError) as exc:
        parser.exit(1, "BLOCKED: " + str(exc) + "\n")
